toolScript:
let isRunning = false;
        let chart = null;
        let pings = [];
        let jitters = [];
        let lastPingTime = null;
        function initChart() {
            const ctx = document.getElementById('jitterChart').getContext('2d');
            chart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: Array(50).fill(""),
                    datasets: [{
                        label: 'Packet Latency (ms)',
                        data: Array(50).fill(null),
                        borderColor: '#10b981',
                        backgroundColor: 'rgba(16, 185, 129, 0.05)',
                        borderWidth: 3,
                        tension: 0.4,
                        pointRadius: 0,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    animation: false,
                    scales: {
                        x: { display: false },
                        y: {
                            beginAtZero: false,
                            grid: { color: '#f1f5f9', drawBorder: false },
                            ticks: {
                                font: { family: 'JetBrains Mono', size: 10, weight: 'bold' },
                                color: '#94a3b8'
                            }
                        }
                    },
                    plugins: { legend: { display: false }, tooltip: { enabled: true } }
                }
            });
        }
        async function performPing() {
            if (!isRunning) return;
            const start = performance.now();
            try {
                // Logic Strategy: HEAD requests minimize bandwidth while providing high-resolution timing.
                // Note: Using a reliable global edge node for consistent baselining.
                await fetch('https://www.google.com/generate_204?cb=' + start, {
                    method: 'HEAD',
                    mode: 'no-cors',
                    cache: 'no-store'
                });
                const end = performance.now();
                const latency = end - start;
                pings.push(latency);
                if (pings.length > 50) pings.shift();
                // Logic: Jitter is the average variation between sequential packet delays.
                if (lastPingTime !== null) {
                    const jitter = Math.abs(latency - lastPingTime);
                    jitters.push(jitter);
                    if (jitters.length > 50) jitters.shift();
                    const avgJitter = jitters.reduce((a, b) => a + b, 0) / jitters.length;
                    const avgLatency = pings.reduce((a, b) => a + b, 0) / pings.length;
                    updateUI(latency, avgJitter, avgLatency);
                }
                lastPingTime = latency;
                updateChart(latency);
            } catch (e) {
                console.warn("Telemetry interrupt: Packet dropped or blocked.");
            }
            // Loop timing: 500ms allows for human-readable visual feedback.
            setTimeout(performPing, 500);
        }
        function updateUI(latency, jitter, avgLatency) {
            document.getElementById('current-jitter').innerHTML = `${jitter.toFixed(1)}<span class="ms-unit">ms</span>`;
            document.getElementById('stat-latency').innerText = `${Math.round(avgLatency)} ms`;
            document.getElementById('stat-samples').innerText = pings.length;
            const ratingEl = document.getElementById('stat-rating');
            if (jitter < 10) {
                ratingEl.innerText = "Elite";
                ratingEl.className = "text-xl font-black text-emerald-600 tracking-tighter";
            } else if (jitter < 30) {
                ratingEl.innerText = "Jittery";
                ratingEl.className = "text-xl font-black text-amber-500 tracking-tighter";
            } else {
                ratingEl.innerText = "Fragmented";
                ratingEl.className = "text-xl font-black text-red-600 tracking-tighter";
            }
        }
        function updateChart(latency) {
            chart.data.datasets[0].data.push(latency);
            if (chart.data.datasets[0].data.length > 50) {
                chart.data.datasets[0].data.shift();
            }
            chart.update();
        }
        function toggleAnalysis() {
            isRunning = !isRunning;
            const btn = document.getElementById('start-btn');
            const statusLabel = document.getElementById('chart-status');
            if (isRunning) {
                btn.innerHTML = "<span>CEASE TELEMETRY</span>";
                btn.className = "flex-grow bg-red-600 hover:bg-red-500 text-white font-black py-5 px-10 rounded-2xl shadow-2xl transition transform active:scale-95 flex items-center justify-center gap-3 text-lg uppercase tracking-widest border-b-4 border-red-800";
                statusLabel.innerText = "Stream Live";
                statusLabel.className = "text-[10px] text-emerald-600 font-black animate-pulse";
                performPing();
            } else {
                btn.innerHTML = "<span>INITIALIZE ANALYSIS</span>";
                btn.className = "flex-grow bg-emerald-600 hover:bg-emerald-500 text-white font-black py-5 px-10 rounded-2xl shadow-2xl transition transform active:scale-95 flex items-center justify-center gap-3 text-lg uppercase tracking-widest border-b-4 border-emerald-800";
                statusLabel.innerText = "Scan Paused";
                statusLabel.className = "text-[10px] text-slate-400 font-bold uppercase";
            }
        }
        function resetLog() {
            pings = [];
            jitters = [];
            lastPingTime = null;
            chart.data.datasets[0].data = Array(50).fill(null);
            chart.update();
            document.getElementById('current-jitter').innerHTML = `0.0<span class="ms-unit">ms</span>`;
            document.getElementById('stat-samples').innerText = "0";
            document.getElementById('stat-latency').innerText = "-- ms";
            document.getElementById('stat-rating').innerText = "Standby";
            document.getElementById('stat-rating').className = "text-xl font-black text-slate-300 uppercase tracking-tighter";
            if (isRunning) toggleAnalysis();
        }
        window.onload = function () {
            initChart();
            // Scroll to top
            scrollBtn.onclick = () => window.scrollTo({ top: 0, behavior: 'smooth' });
        };
